const VARSAYILAN_LOGO = "data:image/png;base64,";

function IlkKurulumEkrani({ onOlustur }) {
  const [ad, setAd] = useState("");
  const [kullaniciAdi, setKullaniciAdi] = useState("");
  const [sifre, setSifre] = useState("");
  const [sifreTekrar, setSifreTekrar] = useState("");
  const [bekliyor, setBekliyor] = useState(false);
  const [hata, setHata] = useState(null);

  // İLK YÖNETİCİ BULUT HESABIYLA DOĞRULANIYOR (24 Eylül, v1.445.0). Giriş yalnız bulut hesabıyla
  // yapıldığı için buradaki şifre SAKLANMIYOR (eskiden Tanımlar'a düz metin yazılıyordu ve bir
  // sonraki girişte işe yaramazdı). Hesap Supabase panelinde açılmış olmalı; aynı e-posta + şifreyle
  // giriş tutarsa yönetici kaydı oluşur ve kişi bulut kimliğiyle içeri girer.
  async function gonder() {
    if (bekliyor) return;
    if (!ad.trim() || !kullaniciAdi.trim() || !sifre) return;
    if (sifre !== sifreTekrar) return;
    // Değerler beklemeden ÖNCE sabitleniyor (denetim 18): doğrulanan kimlik ile kaydedilen aynı olsun.
    const temizAd = ad.trim(), temizKA = kullaniciAdi.trim();
    const eposta = kullaniciEposta({ kullaniciAdi: temizKA });
    setBekliyor(true); setHata(null);
    try {
      await supabaseGiris(eposta, sifre);
      setBekliyor(false);
      onOlustur(temizAd, temizKA, eposta);
    } catch (e) {
      setBekliyor(false);
      setHata(`${eposta}: ${bulutGirisSebebi(e)} — hesap Supabase > Authentication > Users'ta bu e-postayla açılmış olmalı.`);
    }
  }

  return (
    <div style={{ minHeight: "100vh", background: "var(--erp-panel-2)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif" }}>
      <div style={{ background: "#fff", border: "1px solid var(--erp-line-soft)", borderRadius: "var(--erp-r-lg)", padding: 32, width: 380 }}>
        <div style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 20, fontWeight: 700, marginBottom: 4 }}>Atölye ERP — İlk Kurulum</div>
        <p style={{ fontSize: 13, color: "var(--erp-text-2)", margin: "0 0 20px" }}>
          Sistemi ilk kez kuruyorsunuz. Önce Supabase panelinde kendinize bir hesap açın
          (kullanıcıadı@atolye.local), sonra aynı kullanıcı adı ve şifreyle buradan Yönetici olun.
        </p>
        <div style={{ display: "grid", gap: 12 }}>
          <Field label="Adınız">
            <input value={ad} onChange={(e) => setAd(e.target.value)} style={inputStyle} placeholder="örn. Ahmet Yılmaz" />
          </Field>
          <Field label="Kullanıcı Adı">
            <input value={kullaniciAdi} onChange={(e) => setKullaniciAdi(e.target.value)} style={inputStyle} placeholder="örn. ahmet" />
          </Field>
          <Field label="Şifre">
            <input type="password" value={sifre} onChange={(e) => setSifre(e.target.value)} style={inputStyle} />
          </Field>
          <Field label="Şifre (Tekrar)">
            <input type="password" value={sifreTekrar} onChange={(e) => setSifreTekrar(e.target.value)} style={inputStyle} />
          </Field>
          {sifre && sifreTekrar && sifre !== sifreTekrar && (
            <div style={{ fontSize: 12, color: "var(--erp-warn)" }}>Şifreler eşleşmiyor</div>
          )}
        </div>
        {hata && (
          <div data-giris-hatasi="1" style={{ marginTop: 12, fontSize: 12, color: "var(--erp-warn)", background: "var(--erp-orange-bg)", border: "1px solid #E1611F", borderRadius: "var(--erp-r-md)", padding: "8px 10px" }}>
            {hata}
          </div>
        )}
        <button
          className="btn-primary"
          style={{ width: "100%", justifyContent: "center", marginTop: 20, opacity: bekliyor ? 0.6 : 1 }}
          onClick={gonder}
          disabled={bekliyor || !ad.trim() || !kullaniciAdi.trim() || !sifre || sifre !== sifreTekrar}
        >
          {bekliyor ? "Bulut hesabı doğrulanıyor…" : "Yönetici Hesabı Oluştur ve Başla"}
        </button>
      </div>
    </div>
  );
}

function GirisEkrani({ kullanicilar, onGiris, showToast }) {
  const [kullaniciAdi, setKullaniciAdi] = useState("");
  const [sifre, setSifre] = useState("");
  const [bekliyor, setBekliyor] = useState(false);
  // SEBEP KALICI KUTUDA (24 Eylül, v1.445.0): toast birkaç saniyede kayboluyor; "neden
  // giremiyorum" sorusunun cevabı (hesap onaysız, bağlantı yok, şifre hatalı…) ekranda durmalı.
  const [hata, setHata] = useState(null);

  // YEREL ŞİFRE YEDEĞİ KALDIRILDI (24 Eylül, v1.445.0 — kullanıcı kimlik doğrulamayı açtı, son
  // yerel hesabı sildi, "hazır" dedi). Giriş YALNIZ Supabase'den. Eskiden bulut reddedince
  // Tanımlar'daki DÜZ METİN şifreyle içeri alınıyordu; o yol hem şifreyi buluta açık taşıyordu
  // hem de bulutun reddini (yanlış şifre dâhil) sessizce aşıyordu. Bulut yoksa giriş YOK.
  async function girisYap() {
    if (bekliyor) return;
    const ad = kullaniciAdi.trim();
    if (!ad || !sifre) { setHata("Kullanıcı adı ve şifre gerekli"); return; }
    const bulunan = kullanicilar.find(
      (k) => k.kullaniciAdi.toLocaleLowerCase("tr-TR") === ad.toLocaleLowerCase("tr-TR")
    );
    // Kullanıcı adı bulunamadığında da şifre hatalıymış gibi davranılıyor: hangi kullanıcı
    // adlarının var olduğunu deneme yanılmayla öğrenmeyi zorlaştırır.
    if (!bulunan) { setHata("Kullanıcı adı veya şifre hatalı"); showToast("Kullanıcı adı veya şifre hatalı"); return; }

    setBekliyor(true); setHata(null);
    const eposta = kullaniciEposta(bulunan);
    try {
      // DOĞRULAMA YALNIZ BURADA: şifre sunucuda kontrol ediliyor, tarayıcıya hiç inmiyor.
      await supabaseGiris(eposta, sifre);
      setBekliyor(false);
      onGiris(bulunan, true);
    } catch (e) {
      setBekliyor(false);
      const sebep = bulutGirisSebebi(e);
      setHata(`${eposta}: ${sebep}`);
      showToast("Giriş yapılamadı");
    }
  }

  return (
    <div data-giris-ekrani="1" style={{ minHeight: "100vh", background: "var(--erp-panel-2)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif" }}>
      <div style={{ background: "#fff", border: "1px solid var(--erp-line-soft)", borderRadius: "var(--erp-r-lg)", padding: 32, width: 340 }}>
        <div style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 20, fontWeight: 700, marginBottom: 20 }}>Atölye ERP</div>
        <div style={{ display: "grid", gap: 12 }}>
          <Field label="Kullanıcı Adı">
            <input
              value={kullaniciAdi}
              onChange={(e) => setKullaniciAdi(e.target.value)}
              style={inputStyle}
              onKeyDown={(e) => e.key === "Enter" && girisYap()}
              autoFocus
            />
          </Field>
          <Field label="Şifre">
            <input
              type="password"
              value={sifre}
              onChange={(e) => setSifre(e.target.value)}
              style={inputStyle}
              onKeyDown={(e) => e.key === "Enter" && girisYap()}
            />
          </Field>
        </div>
        {hata && (
          <div data-giris-hatasi="1" style={{ marginTop: 12, fontSize: 12, color: "var(--erp-warn)", background: "var(--erp-orange-bg)", border: "1px solid #E1611F", borderRadius: "var(--erp-r-md)", padding: "8px 10px" }}>
            {hata}
          </div>
        )}
        <button className="btn-primary" disabled={bekliyor} style={{ width: "100%", justifyContent: "center", marginTop: 20, opacity: bekliyor ? 0.6 : 1 }} onClick={girisYap}>
          {bekliyor ? "Doğrulanıyor…" : "Giriş Yap"}
        </button>
      </div>
    </div>
  );
}

// ================= BULUT ÖN GİRİŞ EKRANI (2. aşama) =================
//
// rls-kimlik.sql çalıştırıldıktan sonra veritabanı anahtarla OKUNAMAZ; uygulama açılışta veriyi
// çekemez, dolayısıyla kullanıcı listesini de bilemez. Bu ekran veriden ÖNCE gelir: kullanıcı
// adı + şifre → Supabase Auth; e-posta kullanıcı adından türetilir (Tanımlar'daki kuralın aynısı,
// `kullaniciEposta`). Girişten sonra App veriyi yeniden yükler ve kullanıcıyı Tanımlar'daki
// kayıtla eşleyip doğrudan içeri alır — ikinci bir giriş ekranı sorulmaz.
//
// Yerel şifre yedeği BURADA YOK: veri okunamıyorsa yerel şifreyi karşılaştıracak kayıt da yok.
function BulutGirisEkrani({ sebep, onGiris, showToast }) {
  const [kullaniciAdi, setKullaniciAdi] = useState("");
  const [sifre, setSifre] = useState("");
  const [bekliyor, setBekliyor] = useState(false);
  const [hata, setHata] = useState(null);

  async function girisYap() {
    if (bekliyor) return;
    const ad = kullaniciAdi.trim();
    if (!ad || !sifre) { showToast("Kullanıcı adı ve şifre gerekli"); return; }
    const eposta = kullaniciEposta({ kullaniciAdi: ad });
    setBekliyor(true); setHata(null);
    try {
      await supabaseGiris(eposta, sifre);
      onGiris({ kullaniciAdi: ad, eposta });
    } catch (e) {
      setHata(`${eposta}: ${bulutGirisSebebi(e)}`);
    } finally {
      setBekliyor(false);
    }
  }

  return (
    <div style={{ minHeight: "100vh", background: "var(--erp-panel-2)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif" }}>
      <div data-bulut-giris-ekrani="1" style={{ background: "#fff", border: "1px solid var(--erp-line-soft)", borderRadius: "var(--erp-r-lg)", padding: 32, width: 360 }}>
        <div style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 20, fontWeight: 700, marginBottom: 6 }}>Atölye ERP</div>
        <div style={{ fontSize: 12, color: "var(--erp-text-2)", marginBottom: 18 }}>
          Bulut kimliğiyle giriş — veriler yalnız giriş yapmış kullanıcıya açık.
        </div>
        <div style={{ display: "grid", gap: 12 }}>
          <Field label="Kullanıcı Adı">
            <input value={kullaniciAdi} onChange={(e) => setKullaniciAdi(e.target.value)} style={inputStyle}
              onKeyDown={(e) => e.key === "Enter" && girisYap()} autoFocus />
          </Field>
          <Field label="Şifre">
            <input type="password" value={sifre} onChange={(e) => setSifre(e.target.value)} style={inputStyle}
              onKeyDown={(e) => e.key === "Enter" && girisYap()} />
          </Field>
        </div>
        {hata && (
          <div data-bulut-giris-hata="1" style={{ marginTop: 12, fontSize: 12, color: "var(--erp-warn)", background: "var(--erp-orange-bg)", border: "1px solid #E1611F", borderRadius: "var(--erp-r-md)", padding: "8px 10px" }}>
            {hata}
          </div>
        )}
        <button className="btn-primary" disabled={bekliyor} style={{ width: "100%", justifyContent: "center", marginTop: 20, opacity: bekliyor ? 0.6 : 1 }} onClick={girisYap}>
          {bekliyor ? "Doğrulanıyor…" : "Giriş Yap"}
        </button>
        {sebep && (
          <div style={{ marginTop: 14, fontSize: 11, color: "var(--erp-text-3)" }} title={sebep}>
            {sebep === "oturum-dustu"
              ? "Oturumunuz kapandı. Giriş yapınca bu cihazda bekleyen kayıtlar buluta gönderilir — hiçbir şey kaybolmadı."
              : "Veritabanı anahtarla okunamadı (2. aşama etkin). Bulut hesabınız yoksa yöneticinize başvurun."}
          </div>
        )}
      </div>
    </div>
  );
}

function StitchDivider({ color = "var(--erp-border)" }) {
  return (
    <div
      aria-hidden="true"
      style={{
        height: 1,
        backgroundImage:
          `repeating-linear-gradient(90deg, ${color} 0, ${color} 6px, transparent 6px, transparent 12px)`,
        margin: "18px 0",
      }}
    />
  );
}

